create extension if not exists pgcrypto;
create table if not exists public.businesses(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,slug text unique not null,name text not null,category text not null default 'Tour Operator',city text,state text,country text not null default 'India',address text,phone text,whatsapp text,website text,email text,about text,services text[] default '{}',opening_hours jsonb default '{}',cover_image text,verified boolean not null default false,subscription_status text not null default 'inactive',published boolean not null default false,views bigint not null default 0,leads bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.business_photos(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,url text not null,caption text default '',sort_order integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.reviews(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,author_name text not null,rating integer not null check(rating between 1 and 5),title text default '',body text not null,created_at timestamptz not null default now(),unique(business_id,user_id));
create table if not exists public.enquiries(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,phone text,email text,message text not null,created_at timestamptz not null default now(),status text not null default 'new');
create table if not exists public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,business_id uuid references public.businesses(id) on delete set null,razorpay_subscription_id text unique,razorpay_plan_id text,status text not null default 'created',current_start timestamptz,current_end timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.business_views(id bigint generated always as identity primary key,business_id uuid not null references public.businesses(id) on delete cascade,viewed_at timestamptz not null default now());
create or replace function public.set_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end;$$;
drop trigger if exists businesses_updated_at on public.businesses;create trigger businesses_updated_at before update on public.businesses for each row execute function public.set_updated_at();
create or replace function public.increment_business_views(business_id_param uuid) returns void language sql security definer as $$update public.businesses set views=views+1 where id=business_id_param;$$;
create or replace function public.increment_business_leads(business_id_param uuid) returns void language sql security definer as $$update public.businesses set leads=leads+1 where id=business_id_param;$$;
alter table public.businesses enable row level security;alter table public.business_photos enable row level security;alter table public.reviews enable row level security;alter table public.enquiries enable row level security;alter table public.subscriptions enable row level security;alter table public.business_views enable row level security;
create policy "public reads published businesses" on public.businesses for select using(published=true);create policy "owners manage businesses" on public.businesses for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy "public reads photos" on public.business_photos for select using(exists(select 1 from public.businesses b where b.id=business_id and b.published=true));create policy "owners manage photos" on public.business_photos for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy "public reads reviews" on public.reviews for select using(true);create policy "users create reviews" on public.reviews for insert with check(auth.uid()=user_id);create policy "users edit own reviews" on public.reviews for update using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "users delete own reviews" on public.reviews for delete using(auth.uid()=user_id);
create policy "public sends enquiries" on public.enquiries for insert with check(true);create policy "owners read enquiries" on public.enquiries for select using(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid()));create policy "owners update enquiries" on public.enquiries for update using(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid()));
create policy "owners read subscriptions" on public.subscriptions for select using(auth.uid()=user_id);
create policy "public records views" on public.business_views for insert with check(true);create policy "owners read views" on public.business_views for select using(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid()));
insert into storage.buckets(id,name,public) values('business-media','business-media',true) on conflict(id) do nothing;
create policy "public media read" on storage.objects for select using(bucket_id='business-media');create policy "owners upload media" on storage.objects for insert with check(bucket_id='business-media' and auth.uid()::text=(storage.foldername(name))[1]);create policy "owners update media" on storage.objects for update using(bucket_id='business-media' and auth.uid()::text=(storage.foldername(name))[1]);create policy "owners delete media" on storage.objects for delete using(bucket_id='business-media' and auth.uid()::text=(storage.foldername(name))[1]);
